fn next_evm_env(
    &self,
    parent: &Header,
    attributes: &NextBlockEnvAttributes,
) -> Result<EvmEnv, Self::Error> {
    // ensure we're not missing any timestamp based hardforks
    let chain_spec = self.chain_spec();
    let blob_params = chain_spec.blob_params_at_timestamp(attributes.timestamp);
    let spec_id = revm_spec_by_timestamp_and_block_number(
        chain_spec,
        attributes.timestamp,
        parent.number() + 1,
    );

    // configure evm env based on parent block
    let mut cfg =
        CfgEnv::new().with_chain_id(self.chain_spec().chain().id()).with_spec(spec_id);

    if let Some(blob_params) = &blob_params {
        cfg.set_max_blobs_per_tx(blob_params.max_blobs_per_tx);
    }

    if self.chain_spec().is_osaka_active_at_timestamp(attributes.timestamp) {
        cfg.tx_gas_limit_cap = Some(MAX_TX_GAS_LIMIT_OSAKA);
    }

    // if the parent block did not have excess blob gas (i.e. it was pre-cancun), but it is
    // cancun now, we need to set the excess blob gas to the default value(0)
    let blob_excess_gas_and_price = parent
        .maybe_next_block_excess_blob_gas(blob_params)
        .or_else(|| (spec_id == SpecId::CANCUN).then_some(0))
        .map(|excess_blob_gas| {
            let blob_gasprice =
                blob_params.unwrap_or_else(BlobParams::cancun).calc_blob_fee(excess_blob_gas);
            BlobExcessGasAndPrice { excess_blob_gas, blob_gasprice }
        });

    let mut basefee = chain_spec.next_block_base_fee(parent, attributes.timestamp);

    let mut gas_limit = attributes.gas_limit;

    // If we are on the London fork boundary, we need to multiply the parent's gas limit by the
    // elasticity multiplier to get the new gas limit.
    if self.chain_spec().fork(EthereumHardfork::London).transitions_at_block(parent.number + 1)
    {
        let elasticity_multiplier = self
            .chain_spec()
            .base_fee_params_at_timestamp(attributes.timestamp)
            .elasticity_multiplier;

        // multiply the gas limit by the elasticity multiplier
        gas_limit *= elasticity_multiplier as u64;

        // set the base fee to the initial base fee from the EIP-1559 spec
        basefee = Some(INITIAL_BASE_FEE)
    }

    let block_env = BlockEnv {
        number: U256::from(parent.number + 1),
        beneficiary: attributes.suggested_fee_recipient,
        timestamp: U256::from(attributes.timestamp),
        difficulty: U256::ZERO,
        prevrandao: Some(attributes.prev_randao),
        gas_limit,
        // calculate basefee based on parent block's gas usage
        basefee: basefee.unwrap_or_default(),
        // calculate excess gas based on parent block's blob gas usage
        blob_excess_gas_and_price,
    };

    Ok((cfg, block_env).into())
}

fn context_for_block<'a>(&self, block: &'a SealedBlock<Block>) -> EthBlockExecutionCtx<'a> {
    EthBlockExecutionCtx {

    fn assemble_block(
        &self,
        input: BlockAssemblerInput<'_, '_, F>,
    ) -> Result<Block<TransactionSigned>, BlockExecutionError> {
        let BlockAssemblerInput {
            evm_env,
            execution_ctx: ctx,
            parent,
            transactions,
            output: BlockExecutionResult { receipts, requests, gas_used },
            state_root,
            ..
        } = input;

        let timestamp = evm_env.block_env.timestamp.saturating_to();

        let transactions_root = proofs::calculate_transaction_root(&transactions);
        let receipts_root = Receipt::calculate_receipt_root_no_memo(receipts);
        let logs_bloom = logs_bloom(receipts.iter().flat_map(|r| r.logs()));

        let withdrawals = self
            .chain_spec
            .is_shanghai_active_at_timestamp(timestamp)
            .then(|| ctx.withdrawals.map(|w| w.into_owned()).unwrap_or_default());

        let withdrawals_root =
            withdrawals.as_deref().map(|w| proofs::calculate_withdrawals_root(w));
        let requests_hash = self
            .chain_spec
            .is_prague_active_at_timestamp(timestamp)
            .then(|| requests.requests_hash());

        let mut excess_blob_gas = None;
        let mut blob_gas_used = None;

        // only determine cancun fields when active
        if self.chain_spec.is_cancun_active_at_timestamp(timestamp) {
            blob_gas_used =
                Some(transactions.iter().map(|tx| tx.blob_gas_used().unwrap_or_default()).sum());
            excess_blob_gas = if self.chain_spec.is_cancun_active_at_timestamp(parent.timestamp) {
                parent.maybe_next_block_excess_blob_gas(
                    self.chain_spec.blob_params_at_timestamp(timestamp),
                )
            } else {
                // for the first post-fork block, both parent.blob_gas_used and
                // parent.excess_blob_gas are evaluated as 0
                Some(
                    alloy_eips::eip7840::BlobParams::cancun()
                        .next_block_excess_blob_gas_osaka(0, 0, 0),
                )
            };
        }

        let header = Header {
            parent_hash: ctx.parent_hash,
            ommers_hash: EMPTY_OMMER_ROOT_HASH,
            beneficiary: evm_env.block_env.beneficiary,
            state_root,
            transactions_root,
            receipts_root,
            withdrawals_root,
            logs_bloom,
            timestamp,
            mix_hash: evm_env.block_env.prevrandao.unwrap_or_default(),
            nonce: BEACON_NONCE.into(),
            base_fee_per_gas: Some(evm_env.block_env.basefee),
            number: evm_env.block_env.number.saturating_to(),
            gas_limit: evm_env.block_env.gas_limit,
            difficulty: evm_env.block_env.difficulty,
            gas_used: *gas_used,
            extra_data: self.extra_data.clone(),
            parent_beacon_block_root: ctx.parent_beacon_block_root,
            blob_gas_used,
            excess_blob_gas,
            requests_hash,
        };

        Ok(Block {
            header,
            body: BlockBody { transactions, ommers: Default::default(), withdrawals },
        })
    }
}

